{"implementation": "def solve(case):
    initial_state = case["initial_state"]
    max_steps = case["max_steps"]
    tool_observations = case["tool_observations"]
    transitions = case["transitions"]
    current_state = initial_state
    step = 0
    trace = []
    while step < max_steps and current_state in transitions and transitions[current_state]["kind"] == "action":
        step += 1
        action = transitions[current_state]["action"]
        observation = tool_observations[action]
        next_state = transitions[current_state]["next_by_observation"].get(observation, transitions[current_state]["default_next"])
        trace.append({
            "step": step,
            "action": action,
            "observation": observation,
            "state": next_state
        })
        current_state = next_state
        if current_state in transitions and transitions[current_state]["kind"] == "final":
            return {
                "final": transitions[current_state]["value"],
                "status": "completed",
                "trace": trace
            }
    if current_state in transitions and transitions[current_state]["kind"] == "final":
        return {
            "final": transitions[current_state]["value"],
            "status": "completed",
            "trace": trace
        }
    else:
        return {
            "final": None,
            "status": "max_steps_reached",
            "trace": trace
        }"}
